{"source": "def investigate(context, acquire):
    hist = acquire("history")
    # Family: put mode in {ignore, replace, upsert}, trigger in {none, after_insert},
    # channel in {changes, total_changes, total_changes_sum}.
    # We simulate each candidate and keep those consistent with all receipts.

    def simulate(actions, mode, trig, chan):
        # returns (channel_value, committed_count, committed_sum)
        # state: dict key->value for committed; pending per connection
        committed = {}
        # transaction state per connection: None or dict of pending changes
        # We model writes as applying to a working copy; commit merges, rollback discards.
        # For simplicity track per-connection pending dict and a flag.
        pending = {"main": None, "other": None}
        # total_changes counters per connection
        tc = {"main": 0, "other": 0}
        # last changes() per connection
        last_changes = {"main": 0, "other": 0}
        # log rows count (trigger)
        log = 0

        def apply_put(conn, key, value):
            nonlocal log
            # determine current visible state for this connection
            if pending[conn] is not None:
                view = dict(committed)
                view.update(pending[conn])
            else:
                view = committed
            changed = 0
            if mode == "ignore":
                if key not in view:
                    changed = 1
            elif mode == "replace":
                changed = 1
            else:  # upsert
                if key in view:
                    if view[key] != value:
                        changed = 1
                else:
                    changed = 1
            if changed:
                if pending[conn] is not None:
                    pending[conn][key] = value
                else:
                    committed[key] = value
                tc[conn] += 1
                if trig:
                    log += 1
            last_changes[conn] = changed

        def apply_update(conn, key, value):
            nonlocal log
            if pending[conn] is not None:
                view = dict(committed)
                view.update(pending[conn])
            else:
                view = committed
            changed = 0
            if key in view and view[key] != value:
                changed = 1
            if changed:
                if pending[conn] is not None:
                    pending[conn][key] = value
                else:
                    committed[key] = value
                tc[conn] += 1
                if trig:
                    log += 1
            last_changes[conn] = changed

        def apply_delete(conn, key):
            nonlocal log
            if pending[conn] is not None:
                view = dict(committed)
                view.update(pending[conn])
            else:
                view = committed
            changed = 0
            if key in view:
                changed = 1
            if changed:
                if pending[conn] is not None:
                    del pending[conn][key]
                else:
                    del committed[key]
                tc[conn] += 1
                if trig:
                    log += 1
            last_changes[conn] = changed

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                apply_put(conn, act["key"], act["value"])
            elif op == "update":
                apply_update(conn, act["key"], act["value"])
            elif op == "delete":
                apply_delete(conn, act["key"])
            elif op == "begin":
                pending[conn] = {}
            elif op == "commit":
                if pending[conn] is not None:
                    committed.update(pending[conn])
                    pending[conn] = None
            elif op == "rollback":
                pending[conn] = None

        if chan == "changes":
            ch = last_changes["main"]
        elif chan == "total_changes":
            ch = tc["main"]
        else:
            ch = tc["main"] + tc["other"]
        return ch, len(committed), sum(committed.values())

    modes = ["ignore", "replace", "upsert"]
    trigs = [False, True]
    chans = ["changes", "total_changes", "total_changes_sum"]

    candidates = []
    for mode in modes:
        for trig in trigs:
            for chan in chans:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    ch, cc, cs = simulate(acts, mode, trig, chan)
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((mode, trig, chan))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for mode, trig, chan in candidates:
        ch, cc, cs = simulate(actions, mode, trig, chan)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
        else:
            return {"value": None, "unresolved": True}
    if len(vals) == 1:
        return {"value": vals.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Family of 18 SQLite put/trigger/channel combinations; predicts channel, committed_count, committed_sum from calibration receipts.", "lesson": "Simulate all 18 family members against receipts, keep consistent ones, and answer only when all survivors agree on the goal."}
